def find_minimal_edit(s_in, s_out):
    """Find the minimal edit operation between two strings"""
    # Simple approach: find first position where chars differ
    min_len = min(len(s_in), len(s_out))

    # Check for insertion/deletion
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Check if we're inserting or deleting
            if len(s_in) > len(s_out):
                # Deletion case - s_out is shorter
                return (s_in[i], '', i)
            elif len(s_in) < len(s_out):
                # Insertion case - s_out is longer  
                return ('', s_out[i], i)
            else:
                # Substitution case
                return (s_in[i], s_out[i], i)

    # If we reach here, one string is prefix of the other
    if len(s_in) > len(s_out):
        # Deletion at end
        return (s_in[min_len], '', min_len)
    elif len(s_in) < len(s_out):
        # Insertion at end
        return ('', s_out[min_len], min_len)
    else:
        # Strings are identical
        return ('', '', -1)

